-- Questions whose stem or original answer explanation depends on diagrams/tables are deferred.
-- Batch: DS-2027-ORIGINAL-CH8-D-TEXT-ONLY

CREATE TABLE ds_2027_original_ch8_d_text_import (
    num INTEGER PRIMARY KEY,
    id VARCHAR(36) NOT NULL,
    kp_code VARCHAR(64) NOT NULL,
    difficulty VARCHAR(16) NOT NULL,
    source_type VARCHAR(32) NOT NULL,
    source_year INTEGER,
    section_tag VARCHAR(64) NOT NULL,
    source_pages VARCHAR(64) NOT NULL,
    stem TEXT NOT NULL,
    answer TEXT NOT NULL,
    explanation TEXT NOT NULL,
    option_a TEXT NOT NULL,
    option_b TEXT NOT NULL,
    option_c TEXT NOT NULL,
    option_d TEXT NOT NULL
);

INSERT INTO ds_2027_original_ch8_d_text_import (
    num, id, kp_code, difficulty, source_type, source_year, section_tag, source_pages,
    stem, answer, explanation, option_a, option_b, option_c, option_d
) VALUES
(1, '00000000-0000-0000-0000-000000071001', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2015, '8.5归并、基数和计数排序', 'pp.369,371', '【2015 统考真题】下列排序算法中，元素的移动次数与关键字的初始状态无关的是（ ）。', 'C', '基数排序按各位进行固定次数的分配和收集，元素移动次数与关键字初始状态无关；直接插入排序、冒泡排序和快速排序的移动次数均与初始状态有关。', '直接插入排序', '冒泡排序', '基数排序', '快速排序'),
(2, '00000000-0000-0000-0000-000000071002', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2021, '8.5归并、基数和计数排序', 'pp.369,371', '【2021 统考真题】设数组 S[]={93,946,372,9,146,151,301,485,236,327,43,892}，采用最低位优先（LSD）基数排序将 S 排列成升序序列。第一趟分配、收集后，元素 372 之前、之后紧邻的元素分别为（ ）。', 'C', '最低位优先基数排序的第一趟按照个位数字稳定分配、收集，得到 {151,301,372,892,93,43,485,946,146,236,327,9}，因此 372 的前后相邻元素分别为 301 和 892。', '43,892', '236,301', '301,892', '485,301'),
(3, '00000000-0000-0000-0000-000000071003', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'PAST_EXAM', 2022, '8.5归并、基数和计数排序', 'pp.369,371', '【2022 统考真题】使用 2 路归并排序对含 n 个元素的数组 M 进行排序时，2 路归并排序的功能是（ ）。', 'A', '归并排序的基本操作是将两个或两个以上的有序表合并成一个新的有序表；2 路归并就是将两个有序表合并为一个新的有序表。', '将两个有序表合并为一个新的有序表', '将 M 划分为两部分，两部分的元素个数大致相等', '将 M 划分为 n 个部分，每个部分中仅含有一个元素', '将 M 划分为两部分，一部分元素的值均小于另一部分元素的值'),
(4, '00000000-0000-0000-0000-000000071004', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2024, '8.5归并、基数和计数排序', 'pp.369,372', '【2024 统考真题】现有由关键字组成的 3 个有序序列 (3,5)、(7,9) 和 (6)，若按从左至右的次序选择有序序列进行 2 路归并排序，则关键字之间的总比较次数是（ ）。', 'C', '先将 (3,5) 与 (7,9) 归并，需要比较 2 次；再将得到的 (3,5,7,9) 与 (6) 归并，需要比较 3 次，共比较 5 次。', '3', '4', '5', '6'),
(5, '00000000-0000-0000-0000-000000071005', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.374-377', '若要求排序是稳定的，且关键字为实数，则在下列排序算法中应选（ ）。', 'A', '简单选择排序和快速排序是不稳定的；基数排序不能对实数类型的关键字进行排序；直接插入排序稳定且适用于实数关键字。', '直接插入排序', '选择排序', '基数排序', '快速排序'),
(6, '00000000-0000-0000-0000-000000071006', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.375,377', '以下排序算法中时间复杂度为 O(nlog2n) 且稳定的是（ ）。', 'C', '堆排序和快速排序都不稳定，直接插入排序的平均时间复杂度为 O(n^2)，归并排序的时间复杂度为 O(nlog2n) 且稳定。', '堆排序', '快速排序', '归并排序', '直接插入排序'),
(7, '00000000-0000-0000-0000-000000071007', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.375,377', '设被排序的结点序列共有 n 个结点，在该序列中的结点已十分接近有序的情况下，用直接插入排序、归并排序和快速排序对其进行排序，这些算法的时间复杂度为（ ）。', 'C', '序列已十分接近有序时，直接插入排序接近最好情况，时间复杂度为 O(n)；归并排序始终为 O(nlog2n)；快速排序在这种情况下接近最坏情况，为 O(n^2)。', 'O(n)，O(n)，O(n)', 'O(n)，O(nlog2n)，O(nlog2n)', 'O(n)，O(nlog2n)，O(n^2)', 'O(n^2)，O(nlog2n)，O(n^2)'),
(8, '00000000-0000-0000-0000-000000071008', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.375,377', '就排序算法所用的辅助空间而言，堆排序、快速排序和归并排序的关系是（ ）。', 'A', '堆排序所需辅助空间为 O(1)，快速排序平均为 O(log2n)，归并排序为 O(n)，因此辅助空间大小关系为堆排序小于快速排序小于归并排序。', '堆排序<快速排序<归并排序', '堆排序<归并排序<快速排序', '堆排序>归并排序>快速排序', '堆排序>快速排序>归并排序'),
(9, '00000000-0000-0000-0000-000000071009', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.375,377', '排序趟数与序列的初始状态无关的排序算法是（ ）。\nI. 快速排序\nII. 简单选择排序\nIII. 冒泡排序\nIV. 基数排序', 'B', '简单选择排序固定需要 n-1 趟，基数排序的趟数取决于关键字位数，均与初始状态无关；快速排序和冒泡排序的趟数会受到初始状态影响。', 'I、III', 'II、IV', 'I、II、IV', 'I、IV'),
(10, '00000000-0000-0000-0000-000000071010', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.375,377', '排序趟数与序列的初始状态有关的排序算法是（ ）。', 'C', '快速排序每趟划分得到的子序列规模与初始序列有关，排序趟数也随之变化；直接插入排序、2 路归并排序和堆排序的趟数不依赖初始状态。', '直接插入排序', '2 路归并排序', '快速排序', '堆排序'),
(11, '00000000-0000-0000-0000-000000071011', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.375,377', '对 n 个元素进行排序，其排序趟数肯定为 n-1 趟的排序算法是（ ）。', 'C', '直接插入排序和简单选择排序都需要对第 2 个至第 n 个位置逐趟处理，排序趟数固定为 n-1 趟。', '直接插入排序和快速排序', '冒泡排序和快速排序', '简单选择排序和直接插入排序', '简单选择排序和冒泡排序'),
(12, '00000000-0000-0000-0000-000000071012', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.375,377', '若序列的初始状态为 {1,2,3,4,5,10,6,7,8,9}，要想使得排序过程中元素比较次数最少，则应该采用（ ）方法。', 'A', '该序列仅有元素 10 与其后若干元素次序不当，已十分接近有序；直接插入排序在这种初态下比较次数最少。', '直接插入排序', '简单选择排序', '希尔排序', '冒泡排序'),
(13, '00000000-0000-0000-0000-000000071013', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.375,377', '对于元素个数相同的不同初始序列，总比较次数大致相同的排序算法是（ ）。', 'A', '折半插入排序每次插入定位所需比较次数主要由当前有序区长度决定；简单选择排序的比较次数固定。二者的总比较次数与初始序列关系不大。', '折半插入排序和简单选择排序', '基数排序和归并排序', '冒泡排序和快速排序', '堆排序'),
(14, '00000000-0000-0000-0000-000000071014', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.375,377', '一般情况下，以下查找效率最低的数据结构是（ ）。', 'C', '堆只保证父子结点之间满足堆序性质，对查找任意关键字没有整体有序性可利用，因此一般查找效率最低。', '有序顺序表', '二叉排序树', '堆', '平衡二叉树'),
(15, '00000000-0000-0000-0000-000000071015', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.6内部排序比较与应用', 'pp.375,377', '一台计算机具有多核 CPU，可以同时执行相互独立的任务。归并排序的各个归并段可以并行执行，在下列排序算法中，不可以并行执行的有（ ）。\nI. 基数排序\nII. 快速排序\nIII. 冒泡排序\nIV. 堆排序', 'A', '基数排序中后一趟分配和收集依赖前一趟结果，冒泡排序中每趟处理也依赖此前序列，二者不宜并行；快速排序划分后的子表和堆排序的子堆可独立处理。', 'I、III', 'I、II', 'I、III、IV', 'II、IV'),
(16, '00000000-0000-0000-0000-000000071016', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2009, '8.6内部排序比较与应用', 'pp.375,377-378', '【2009 统考真题】若数据元素序列 {11,12,13,7,8,9,23,4,5} 是采用下列排序算法之一得到的第二趟排序后的结果，则该排序算法只能是（ ）。', 'B', '该序列不符合冒泡排序或简单选择排序第二趟应固定末端或前端极值的特征，也不符合 2 路归并排序第二趟各长度为 4 的段已有序的特征，因此只能是直接插入排序。', '冒泡排序', '直接插入排序', '简单选择排序', '2 路归并排序'),
(17, '00000000-0000-0000-0000-000000071017', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2010, '8.6内部排序比较与应用', 'pp.375-378', '【2010 统考真题】对一组数据 {2,12,16,88,5,10} 进行排序，若前 3 趟排序结果如下：\n第一趟排序结果：2,12,16,5,10,88\n第二趟排序结果：2,12,5,10,16,88\n第三趟排序结果：2,5,10,12,16,88\n则采用的排序算法可能是（ ）。', 'A', '每一趟均通过相邻比较将当前最大元素移动到未排序区末端，给出的三趟结果符合冒泡排序过程。', '冒泡排序', '希尔排序', '归并排序', '基数排序'),
(18, '00000000-0000-0000-0000-000000071018', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2012, '8.6内部排序比较与应用', 'pp.375-378', '【2012 统考真题】在内部排序过程中，对尚未确定最终位置的所有元素进行一遍处理称为一趟排序。下列排序算法中，每趟排序结束都至少能够确定一个元素最终位置的方法是（ ）。\nI. 简单选择排序\nII. 希尔排序\nIII. 快速排序\nIV. 堆排序\nV. 2 路归并排序', 'A', '简单选择排序每趟确定当前最小元素，快速排序每趟确定枢轴，堆排序每趟确定堆顶；希尔排序和 2 路归并排序不能保证每趟确定最终位置。', '仅 I、III、IV', '仅 I、III、V', '仅 II、III、IV', '仅 III、IV、V'),
(19, '00000000-0000-0000-0000-000000071019', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2017, '8.6内部排序比较与应用', 'pp.375-378', '【2017 统考真题】在内部排序时，若选择了归并排序而未选择插入排序，则可能的理由是（ ）。\nI. 归并排序的程序代码更短\nII. 归并排序的占用空间更少\nIII. 归并排序的运行效率更高', 'B', '归并排序的代码并不比插入排序短，且需要 O(n) 的辅助空间而非更少空间；归并排序的时间复杂度为 O(nlog2n)，运行效率可能高于插入排序。', '仅 II', '仅 III', '仅 I、II', '仅 I、III'),
(20, '00000000-0000-0000-0000-000000071020', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2017, '8.6内部排序比较与应用', 'pp.375-378', '【2017 统考真题】下列排序算法中，若将顺序存储更换为链式存储，则算法的时间效率会降低的是（ ）。\nI. 插入排序\nII. 选择排序\nIII. 冒泡排序\nIV. 希尔排序\nV. 堆排序', 'D', '希尔排序和堆排序都依赖顺序存储提供的随机访问能力，改为链式存储会降低时间效率；插入排序、选择排序和冒泡排序的数量级不因此改变。', '仅 I、II', '仅 II、III', '仅 III、IV', '仅 IV、V'),
(21, '00000000-0000-0000-0000-000000071021', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'PAST_EXAM', 2019, '8.6内部排序比较与应用', 'pp.376,378', '【2019 统考真题】选择一个排序算法时，除算法的时空效率外，下列因素中，还需要考虑的是（ ）。\nI. 数据的规模\nII. 数据的存储方式\nIII. 算法的稳定性\nIV. 数据的初始状态', 'D', '数据规模、存储方式、稳定性要求和数据初始状态都会影响适合采用的排序算法，因此四项均需要考虑。', '仅 III', '仅 I、II', '仅 II、III、IV', 'I、II、III、IV'),
(22, '00000000-0000-0000-0000-000000071022', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2020, '8.6内部排序比较与应用', 'pp.376,378-379', '【2020 统考真题】对大部分元素已有序的数组排序时，直接插入排序比简单选择排序效率更高，其原因是（ ）。\nI. 直接插入排序过程中元素之间的比较次数更少\nII. 直接插入排序过程中所需的辅助空间更少\nIII. 直接插入排序过程中元素的移动次数更少', 'A', '数组大部分已有序时，直接插入排序比较次数明显减少。两种排序所需辅助空间均为 O(1)；元素移动次数也不能据此断定直接插入排序更少，因此只有 I 正确。', '仅 I', '仅 II', '仅 I、II', 'I、II和III'),
(23, '00000000-0000-0000-0000-000000071023', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2022, '8.6内部排序比较与应用', 'pp.376,379', '【2022 统考真题】对数据进行排序时，若采用直接插入排序而不采用快速排序，则可能的原因是（ ）。\nI. 大部分元素已有序\nII. 待排序元素数量很少\nIII. 要求空间复杂度为 O(1)\nIV. 要求排序算法是稳定的', 'D', '直接插入排序在大部分元素已有序或数据量很少时表现良好，辅助空间复杂度为 O(1)，并且是稳定排序；四项都可能成为不采用快速排序的原因。', '仅 I、II', '仅 III、IV', '仅 I、II、IV', 'I、II、III、IV'),
(24, '00000000-0000-0000-0000-000000071024', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'PAST_EXAM', 2023, '8.6内部排序比较与应用', 'pp.376,379', '【2023 统考真题】下列排序算法中，不稳定的是（ ）。\nI. 希尔排序\nII. 归并排序\nIII. 快速排序\nIV. 堆排序\nV. 基数排序', 'C', '希尔排序、快速排序和堆排序是不稳定排序；归并排序和基数排序是稳定排序。', '仅 I、II', '仅 II、V', '仅 I、III、IV', '仅 III、IV、V'),
(25, '00000000-0000-0000-0000-000000071025', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'PAST_EXAM', 2025, '8.6内部排序比较与应用', 'pp.376,379', '【2025 统考真题】在下列排序算法中，最坏情况下元素移动次数最少的是（ ）。', 'D', '简单选择排序每趟至多交换一次，最坏情况下的移动次数为 O(n)；冒泡排序、直接插入排序和快速排序最坏情况下移动次数均可达 O(n^2)。', '冒泡排序', '直接插入排序', '快速排序', '简单选择排序'),
(26, '00000000-0000-0000-0000-000000071026', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.7外部排序', 'pp.385-387', '外部排序和内部排序的主要区别是（ ）。', 'B', '外部排序和内部排序最主要的区别是排序过程中是否涉及内存与外存之间的数据交换。', '内部排序的数据量小，而外部排序的数据量大', '内部排序不涉及内、外存数据交换，而外部排序涉及内、外存数据交换', '内部排序的速度快，而外部排序的速度慢', '内部排序所需的内存小，而外部排序所需的内存大'),
(27, '00000000-0000-0000-0000-000000071027', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.7外部排序', 'pp.385-387', '下列关于外部排序的说法中，正确的是（ ）。', 'C', '置换选择排序生成的初始归并段长度不一定相等；外部排序主要时间消耗在内外存数据交换，并包含文件读写操作；败者树是一棵完全二叉树。', '置换选择排序得到的初始归并段的长度一定相等', '内外存交换数据的时间只占总排序时间的一小部分', '败者树是一棵完全二叉树', '外部排序不涉及对文件的读/写操作'),
(28, '00000000-0000-0000-0000-000000071028', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.7外部排序', 'pp.385-387', '多路平衡归并的作用是（ ）。', 'A', '采用 k 路平衡归并可以减少归并趟数；当 m 个初始归并段进行 k 路平衡归并时，所需趟数为 ceil(logk m)。', '减少归并趟数', '减少初始归并段的个数', '便于实现败者树', '以上都对'),
(29, '00000000-0000-0000-0000-000000071029', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.7外部排序', 'pp.385-387', '设在磁盘上存放有 375000 个记录，进行 5 路平衡归并排序，内存工作区能容纳 600 个记录，为把所有记录排好序，需要进行（ ）趟归并排序。', 'B', '初始归并段个数为 375000/600=625，采用 5 路归并所需趟数为 ceil(log5 625)=4。', '3', '4', '5', '6'),
(30, '00000000-0000-0000-0000-000000071030', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.7外部排序', 'pp.385-387', '在下列关于外部排序过程输入/输出缓冲区作用的叙述中，不正确的是（ ）。', 'D', '外部排序的输入/输出缓冲区用于暂存记录、进行内部归并以及产生初始归并段，不承担传送用户界面消息的任务。', '暂存输入/输出记录', '内部归并的工作区', '产生初始归并段的工作区', '传送用户界面的消息'),
(31, '00000000-0000-0000-0000-000000071031', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.7外部排序', 'pp.385-387', '若只需 3 趟排序就可完成 64 个元素的多路归并排序，则选取的归并路数最少是（ ）。', 'C', '归并趟数为 ceil(logk n)，当 k=4、n=64 时归并趟数恰好为 3，因此归并路数至少为 4。', '2', '3', '4', '5'),
(32, '00000000-0000-0000-0000-000000071032', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.7外部排序', 'pp.385-387', '置换-选择排序的作用是（ ）。', 'A', '置换-选择排序是外部排序中生成初始归并段的方法，所产生的初始归并段长度不等，平均长度约为传统等长初始归并段的 2 倍，但它本身不是完整的外部排序算法。', '用于生成外部排序的初始归并段', '完成将一个磁盘文件排序成有序文件的有效的外部排序算法', '生成的初始归并段的长度是内存工作区的 2 倍', '对外部排序中输入/归并/输出的并行处理'),
(33, '00000000-0000-0000-0000-000000071033', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.7外部排序', 'pp.385-387', '一个无序文件的 n 个记录采用置换选择排序产生 m 个有序段，则 m 和 n 的关系是（ ）。', 'D', '置换选择排序产生的有序段个数不仅与记录数 n 有关，也与待排文件初态和内存工作区大小有关，不能归纳为前三项的直接关系。', 'm 与 n 成正比', 'm=log2n', 'm 与 n 成反比', '以上都不对'),
(34, '00000000-0000-0000-0000-000000071034', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.7外部排序', 'pp.385-387', '在由 k 路归并构建的败者树中选取一个关键字最小的记录，则所需时间为（ ）。', 'C', '在败者树中选取最小关键字的时间复杂度取决于败者树的高度，所需时间为 O(log2k)。', 'O(1)', 'O(k)', 'O(log2k)', '以上都不对'),
(35, '00000000-0000-0000-0000-000000071035', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.7外部排序', 'pp.385-387', '下列关于小顶堆和败者树的说法中，正确的是（ ）。\nI. 败者树从下往上维护，每上一层，只需和失败结点比较 1 次\nII. 败者树的每次维护，必定要从叶结点一直走到根结点，不可能从中间停止\nIII. 堆从上往下维护，每下一层，若其左右孩子均不为空，则需比较 2 次\nIV. 堆的每次维护，必定要从根结点一直走到叶结点，不可能从中间停止', 'C', '败者树维护时胜者会逐层调整到根，I、II 正确；小顶堆调整每层需先比较两个孩子再与当前元素比较，III 正确；堆在中间层已满足性质时可以停止，IV 错误。', 'I、III', 'II、III', 'I、II、III', 'I、III、IV'),
(36, '00000000-0000-0000-0000-000000071036', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'MOCK', 2027, '8.7外部排序', 'pp.386-387', '最佳归并树在外部排序中的作用是（ ）。', 'B', '最佳归并树以初始归并段长度为权值构造带权路径长度最小的多叉树，用于设计多路归并排序的优化方案，减少归并过程中的读写记录数。', '完成 m 路归并排序', '设计 m 路归并排序的优化方案', '产生初始归并段', '与锦标赛树的作用类似'),
(37, '00000000-0000-0000-0000-000000071037', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'MOCK', 2027, '8.7外部排序', 'pp.386-387', '在由 m 个初始归并段构建的 k 阶最佳归并树中，不需要补充虚段，则度为 k 的结点个数是（ ）。', 'C', 'k 阶最佳归并树中仅有度为 0 和度为 k 的结点。设度为 k 的结点数为 nk，由 n0=m、n-1=k*nk 和 n=n0+nk 可得 nk=(m-1)/(k-1)。', '(m-1)/k', 'm/k', '(m-1)/(k-1)', '无法确定'),
(38, '00000000-0000-0000-0000-000000071038', 'DS_SORT_INTERNAL_EXTERNAL', 'BASIC', 'PAST_EXAM', 2016, '8.7外部排序', 'pp.386,388', '【2016 统考真题】对 10TB 的数据文件进行排序，应使用的方法是（ ）。', 'D', '10TB 文件无法一次性装入内存，需要在内存与外存之间进行多次数据交换，属于外部排序；外部排序通常采用归并排序。', '希尔排序', '堆排序', '快速排序', '归并排序'),
(39, '00000000-0000-0000-0000-000000071039', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2019, '8.7外部排序', 'pp.386,388', '【2019 统考真题】设外存上有 120 个初始归并段，进行 12 路归并时，为实现最佳归并，需要补充的虚段个数是（ ）。', 'B', '12 路最佳归并树只含度为 0 和度为 12 的结点。要满足 (n-1)%(m-1)=0，120 个叶结点需要补入 2 个权值为 0 的虚段，使叶结点总数变为 122。', '1', '2', '3', '4'),
(40, '00000000-0000-0000-0000-000000071040', 'DS_SORT_INTERNAL_EXTERNAL', 'MEDIUM', 'PAST_EXAM', 2024, '8.7外部排序', 'pp.386,388', '【2024 统考真题】在外排序中，利用败者树对初始为升序的归并段进行多路归并，败者树中记录“冠军”的结点保存的是（ ）。', 'D', '归并升序归并段时每次需要得到当前最小关键字。为能直接定位并继续读取该元素所在归并段，败者树记录“冠军”的结点应保存最小关键字所在的归并段号。', '最大关键字', '最小关键字', '最大关键字所在的归并段号', '最小关键字所在的归并段号');

INSERT INTO questions (
    id, subject_id, chapter_id, type, difficulty, stem, answer, explanation,
    source, source_year, score, status, review_status, review_note,
    stem_format, stem_image_url, reviewed_at, created_at, updated_at
)
SELECT
    CAST(q.id AS UUID),
    s.id,
    c.id,
    'SINGLE_CHOICE',
    q.difficulty,
    q.stem,
    q.answer,
    q.explanation,
    q.source_type,
    q.source_year,
    2.00,
    'PUBLISHED',
    'APPROVED',
    '授权原题导入：/Users/permer/Documents/408资料/2027数据结构_高清带书签版.pdf，第 8 章 8.5.4/8.5.5、8.6.3/8.6.4 与 8.7.6/8.7.7 本节试题精选及答案解析；本批仅导入题干与答案解析均可完整文本呈现的单选题，参考页：' || q.source_pages || '。',
    'PLAIN_TEXT',
    NULL,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM ds_2027_original_ch8_d_text_import q
JOIN subjects s ON s.code = 'DATA_STRUCTURE'
JOIN chapters c ON c.code = 'DS_SORT';

INSERT INTO question_options (id, question_id, label, content, sort_order)
SELECT CAST(CONCAT('00000000-0000-0000-0000-000000171', LPAD(CAST((num * 4 - 3) AS VARCHAR), 3, '0')) AS UUID), CAST(id AS UUID), 'A', option_a, 1
FROM ds_2027_original_ch8_d_text_import
UNION ALL
SELECT CAST(CONCAT('00000000-0000-0000-0000-000000171', LPAD(CAST((num * 4 - 2) AS VARCHAR), 3, '0')) AS UUID), CAST(id AS UUID), 'B', option_b, 2
FROM ds_2027_original_ch8_d_text_import
UNION ALL
SELECT CAST(CONCAT('00000000-0000-0000-0000-000000171', LPAD(CAST((num * 4 - 1) AS VARCHAR), 3, '0')) AS UUID), CAST(id AS UUID), 'C', option_c, 3
FROM ds_2027_original_ch8_d_text_import
UNION ALL
SELECT CAST(CONCAT('00000000-0000-0000-0000-000000171', LPAD(CAST((num * 4) AS VARCHAR), 3, '0')) AS UUID), CAST(id AS UUID), 'D', option_d, 4
FROM ds_2027_original_ch8_d_text_import;

INSERT INTO question_knowledge_points (question_id, knowledge_point_id)
SELECT CAST(q.id AS UUID), kp.id
FROM ds_2027_original_ch8_d_text_import q
JOIN knowledge_points kp ON kp.code = q.kp_code;

INSERT INTO question_tags (id, name, created_at)
SELECT CAST(tag.id AS UUID), tag.name, CURRENT_TIMESTAMP
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000071701', 'DS-2027-ORIGINAL-CH8-D-TEXT-ONLY'),
    ('00000000-0000-0000-0000-000000071702', '8.6内部排序比较与应用'),
    ('00000000-0000-0000-0000-000000071703', '8.7外部排序')
) AS tag(id, name)
WHERE NOT EXISTS (SELECT 1 FROM question_tags existing WHERE existing.name = tag.name);

INSERT INTO question_tag_relations (question_id, tag_id)
SELECT CAST(q.id AS UUID), tag.id
FROM ds_2027_original_ch8_d_text_import q
JOIN question_tags tag ON tag.name IN (
    '2027数据结构',
    'DS-2027-ORIGINAL-CH8-D-TEXT-ONLY',
    '第8章排序',
    q.section_tag,
    '无图片题目',
    '授权原题',
    '本节试题精选',
    '原答案解析',
    '选择题扩容'
) OR (q.source_type = 'PAST_EXAM' AND tag.name = '真题')
WHERE NOT EXISTS (
    SELECT 1 FROM question_tag_relations existing
    WHERE existing.question_id = CAST(q.id AS UUID)
      AND existing.tag_id = tag.id
);

DROP TABLE ds_2027_original_ch8_d_text_import;
